mapper.select:
SELECT *
FROM easybuy_product_category
WHERE name = #{name}
  AND parent_id = #{parentId}
  AND is_delete = 0
    LIMIT 1

SELECT COUNT(*)
FROM easybuy_product
WHERE is_delete = 0
  AND (
    category_level1_id = #{categoryId}
    OR category_level2_id = #{categoryId}
    OR category_level3_id = #{categoryId}
  )

mapper.update:
UPDATE easybuy_product_category
SET is_delete = 1
WHERE id = #{id}
